import math

def is_power_of_three(n):
    if n <= 0:
        return False
    if n == 1:
        return True, 0

    b = 0
    temp = n
    while temp > 1 and temp % 3 == 0:
        temp //= 3
        b += 1

    if temp == 1:
        return True, b
    else:
        return False, -1

solutions = []
A_MAX = 15
C_MAX = 15

for c in range(1, C_MAX + 1):
    for a in range(1, A_MAX + 1):
        # Calculate N = 6^c - 2^a - 1
        N = pow(6, c) - pow(2, a) - 1

        is_pow3, b = is_power_of_three(N)

        if is_pow3:
            solutions.append((a, b, c))

print("Found solutions (a, b, c):")
for sol in solutions:
    print(sol)

