def is_power_of_three(n):
    if n <= 0:
        return False, -1

    b = 0
    temp = n
    while temp > 1 and temp % 3 == 0:
        temp //= 3
        b += 1

    if temp == 1:
        return True, b
    else:
        return False, -1

